    vowels = ['a', 'e', 'i', 'o', 'u']

    # Initialize a memoization dictionary
    cache = {}

    # Define the memoization function
    def memoize(word):
        if word in cache:
            return cache[word]
        else:
            count = 0
            for char in word:
